mapper.update:
UPDATE sys_user
SET status = #{status},
    version = version + 1,
    security_version = security_version + 1,
    updated_at = #{now}
WHERE id = #{userId}
  AND version = #{expectedVersion}

UPDATE sys_user
SET password_hash = #{passwordHash},
    status = #{status},
    credentials_changed_at = #{credentialsChangedAt},
    version = version + 1,
    security_version = security_version + 1,
    updated_at = #{credentialsChangedAt}
WHERE id = #{userId}
  AND version = #{expectedVersion}

UPDATE sys_user
SET version = version + 1,
    security_version = security_version + 1,
    updated_at = #{now}
WHERE id = #{userId}
  AND version = #{expectedVersion}

UPDATE sys_user SET real_name = #{profile.realName}, email = #{profile.email}, phone = #{profile.phone},
    organization = #{profile.organization}, department = #{profile.department}, remark = #{profile.remark},
    status = #{status}, version = version + 1,
    security_version = security_version + CASE WHEN #{securityChanged} THEN 1 ELSE 0 END,
    updated_at = #{now}
WHERE id = #{userId} AND version = #{expectedVersion}
